        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                curr[j] = prev[j - 1]
            else:
                curr[j] = 1 + min(prev[j],      # delete a[i-1]
                                  curr[j - 1],  # insert b[j-1]
                                  prev[j - 1])  # replace
        prev = curr
    return prev[m]

