def solve(grid):
    # Handle empty grid or grid with no columns
    if not grid:
        return 0
    rows = len(grid)
    # Create visited structure matching each row length (allow irregular grids)
    visited = [ [False]*len(row) for row in grid ]
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            # Check bounds for irregular rows
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or grid[i][j] != 1:
                continue
            visited[i][j] = True
            # Explore four directions
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                islands += 1
                bfs(i, j)
    return islands

