def solve(intervals):
    """Merge overlapping or touching intervals.
    Accepts any iterable of length-2 iterables (list, tuple, etc.).
    Returns a list of [start, end] lists sorted by start.
    """
    # Convert to list of [start, end] copies to avoid mutating input
    ivs = []
    for iv in intervals:
        # Ensure we have exactly two elements
        try:
            s, e = iv[0], iv[1]
        except Exception:
            raise ValueError("Invalid interval")
        ivs.append([s, e])
    if not ivs:
        return []
    ivs.sort(key=lambda x: x[0])
    merged = [ivs[0][:]]
    for start, end in ivs[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

