def solve(word1: str, word2: str) -> int:
    # Use O(min(m, n)) space DP for edit distance.
    if len(word1) < len(word2):
        # Ensure word2 is the shorter one for less space.
        word1, word2 = word2, word1
    m, n = len(word1), len(word2)
    # prev[j] holds distance for word1[:i-1] and word2[:j]
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        c1 = word1[i - 1]
        for j in range(1, n + 1):
            if c1 == word2[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j],      # deletion
                                 cur[j - 1],  # insertion
                                 prev[j - 1]) # substitution
        prev = cur
    return prev[n]

