def solve(grid):
    # Handle empty grid or rows with no columns
    if not grid:
        return 0
    rows = len(grid)
    # Determine if any row has columns
    if all(len(row) == 0 for row in grid):
        return 0
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            # bounds check for jagged rows
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if (i, j) in visited or grid[i][j] == 0:
                continue
            visited.add((i, j))
            # explore 4 directions
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands

